fixed_text <- function(value, places) {
  scale <- 10^places
  paste0(
    sprintf("%.0f", floor(value / scale)),
    ".",
    sprintf(paste0("%0", places, "d"), as.integer(value %% scale))
  )
}
pct <- function(count, length) fixed_text(floor(10000 * count / length), 2)
